30	   *
31	   * @param {string} url - The URL to be split.
32	   * @returns {Object} An object containing the protocol and the raw host/path string.
33	   */
34	  const splitUrl = (url) => {
35	    const urlParts = url.split(urlRegexPatterns.protocolAndRestSeparator);
36	    if (urlParts.length === 1) {
37	      return { protocol: '', rawHostAndPath: urlParts[0] };
38	    } else if (urlParts.length === 2) {
39	      const [hostAndPath, _] = urlParts[1].split(urlRegexPatterns.queryStringSeparator);
40	      return { protocol: urlParts[0], rawHostAndPath: hostAndPath };
